-- ATLAS 4.2 - autenticación cerrada y políticas finas por workspace.
CREATE TABLE IF NOT EXISTS atlas_users (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 email text NOT NULL UNIQUE CHECK (length(email) BETWEEN 5 AND 254 AND email = lower(email)),
 display_name text NOT NULL CHECK (length(trim(display_name)) BETWEEN 2 AND 120),
 password_hash text NOT NULL,
 active boolean NOT NULL DEFAULT true,
 platform_admin boolean NOT NULL DEFAULT false,
 created_by uuid,
 created_at timestamptz NOT NULL DEFAULT now(),
 updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS atlas_sessions (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 user_id uuid NOT NULL REFERENCES atlas_users(id) ON DELETE CASCADE,
 token_hash text NOT NULL UNIQUE,
 csrf_hash text NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(),
 expires_at timestamptz NOT NULL,
 revoked_at timestamptz,
 last_seen_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS atlas_sessions_user ON atlas_sessions(user_id,expires_at);
CREATE INDEX IF NOT EXISTS atlas_sessions_active ON atlas_sessions(expires_at) WHERE revoked_at IS NULL;
CREATE TABLE IF NOT EXISTS workspace_roles (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
 role_key text NOT NULL CHECK(role_key ~ '^[a-z][a-z0-9_-]{1,39}$'),
 name text NOT NULL CHECK(length(trim(name)) BETWEEN 2 AND 100),
 system_role boolean NOT NULL DEFAULT false,
 created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(workspace_id,role_key), UNIQUE(workspace_id,id)
);
CREATE TABLE IF NOT EXISTS role_permissions (
 role_id uuid NOT NULL REFERENCES workspace_roles(id) ON DELETE CASCADE,
 permission text NOT NULL CHECK(length(permission) < 100),
 PRIMARY KEY(role_id,permission)
);
CREATE INDEX IF NOT EXISTS idx_role_permissions_role ON role_permissions(role_id);
ALTER TABLE workspace_members ADD COLUMN IF NOT EXISTS role_id uuid REFERENCES workspace_roles(id);
CREATE INDEX IF NOT EXISTS idx_workspace_member_role ON workspace_members(role_id);
INSERT INTO workspace_roles(workspace_id,role_key,name,system_role)
SELECT w.id,p.role_key,p.name,p.role_key='owner' FROM workspaces w
CROSS JOIN (VALUES ('owner','Propietario'),('admin','Administrador'),('functional','Analista funcional'),('technical','Arquitecto técnico'),('viewer','Lector')) AS p(role_key,name)
ON CONFLICT (workspace_id,role_key) DO NOTHING;
