INSERT INTO role_permissions(role_id,permission) SELECT id,'element.technical.view' FROM workspace_roles WHERE role_key IN ('owner','admin','technical') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission) SELECT id,'element.technical.edit' FROM workspace_roles WHERE role_key IN ('owner','admin','technical') ON CONFLICT DO NOTHING;
UPDATE workspace_members m SET role_id=r.id
FROM workspace_roles r WHERE r.workspace_id=m.workspace_id AND r.role_key=(CASE WHEN m.role='editor' THEN 'functional' ELSE m.role END) AND m.role_id IS NULL;
-- Nuevo usuario activo no puede registrarse por endpoint público. Solo admin crea cuentas.
